function canvasContext(id){const canvas=$(id),rect=canvas.getBoundingClientRect(),dpr=Math.min(window.devicePixelRatio||1,2);const w=Math.max(1,rect.width),h=Math.max(1,rect.height);if(canvas.width!==Math.round(w*dpr)||canvas.height!==Math.round(h*dpr)){canvas.width=Math.round(w*dpr);canvas.height=Math.round(h*dpr);}const ctx=canvas.getContext('2d');ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,w,h);return{canvas,ctx,w,h,p:{x:77,y:13,w:Math.max(1,w-102),h:Math.max(1,h-46)}};}
function projection(p,v=file()?.view||bounds()){const waterfall=state.mode==='waterfall';return {point:(t,f)=>waterfall?{x:p.x+(f-v.f0)/(v.f1-v.f0)*p.w,y:p.y+(t-v.t0)/(v.t1-v.t0)*p.h}:{x:p.x+(t-v.t0)/(v.t1-v.t0)*p.w,y:p.y+(v.f1-f)/(v.f1-v.f0)*p.h},world:(x,y)=>waterfall?{t:v.t0+(y-p.y)/p.h*(v.t1-v.t0),f:v.f0+(x-p.x)/p.w*(v.f1-v.f0)}:{t:v.t0+(x-p.x)/p.w*(v.t1-v.t0),f:v.f1-(y-p.y)/p.h*(v.f1-v.f0)}};}
