function handles(b){return[{k:'nw',x:b.x,y:b.y},{k:'n',x:b.x+b.w/2,y:b.y},{k:'ne',x:b.x+b.w,y:b.y},{k:'e',x:b.x+b.w,y:b.y+b.h/2},{k:'se',x:b.x+b.w,y:b.y+b.h},{k:'s',x:b.x+b.w/2,y:b.y+b.h},{k:'sw',x:b.x,y:b.y+b.h},{k:'w',x:b.x,y:b.y+b.h/2}];}
